using System.Windows; using System.Windows.Controls; using System.Windows.Media; using System.Windows.Media.Media3D; using System.Windows.Threading; namespace VishalXOpt.UI.Controls; public partial class SystemCore3D:UserControl{ readonly AxisAngleRotation3D rot=new(new Vector3D(0,1,0),0); readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(30)}; public SystemCore3D(){InitializeComponent(); Build(); timer.Tick+=(s,e)=>rot.Angle=(rot.Angle+0.8)%360; timer.Start();} void Build(){var group=new Model3DGroup(); group.Children.Add(new AmbientLight(Color.FromRgb(38,70,110))); group.Children.Add(new DirectionalLight(Color.FromRgb(120,190,255),new Vector3D(-1,-1,-2))); for(int i=0;i<3;i++){var cube=new GeometryModel3D(Meshes.Cube(1.6-0.25*i),new DiffuseMaterial(new SolidColorBrush(Color.FromRgb((byte)(38+20*i),(byte)(125+20*i),(byte)(225))))); cube.Transform=new RotateTransform3D(rot,new Point3D(0,0,0)); group.Children.Add(cube);} CoreModel.Content=group;} static class Meshes{public static MeshGeometry3D Cube(double s){double a=s/2;var p=new[]{new Point3D(-a,-a,-a),new Point3D(a,-a,-a),new Point3D(a,a,-a),new Point3D(-a,a,-a),new Point3D(-a,-a,a),new Point3D(a,-a,a),new Point3D(a,a,a),new Point3D(-a,a,a)};int[] t={0,1,2,0,2,3,4,6,5,4,7,6,0,4,5,0,5,1,2,6,7,2,7,3,0,3,7,0,7,4,1,5,6,1,6,2};var m=new MeshGeometry3D();foreach(var x in t)m.Positions.Add(p[x]);for(int i=0;i<t.Length;i++)m.TriangleIndices.Add(i);return m;}} }